def compute(vars):
    debt_obligations = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    value = debt_obligations / total_obligations * 100

    return {
        "value": value,
        "trace": {
            "debt_obligations": debt_obligations,
            "total_obligations": total_obligations,
            "ratio": debt_obligations / total_obligations,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
